"""Centralized visual system for the industrial intelligence UI."""
from __future__ import annotations

import streamlit as st


def inject_theme() -> None:
    """Install the application-wide dark, responsive design tokens once per run."""
    st.markdown(
        """
        <style>
        @import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
        :root { --bg-primary:#06101a; --bg-secondary:#0a1925; --card-bg:rgba(14,33,46,.88); --card-bg-strong:#102636; --border:rgba(146,193,207,.17); --text:#edf8fa; --muted:#91aab5; --accent:#61d9df; --accent-blue:#66aaf7; --success:#74dda5; --warning:#ffc36b; --danger:#ff8484; }
        * { box-sizing:border-box; }
        .stApp { background:radial-gradient(circle at 94% -10%,rgba(38,116,150,.23),transparent 30rem),radial-gradient(circle at 3% 38%,rgba(17,89,104,.14),transparent 25rem),var(--bg-primary); color:var(--text); font-family:'Manrope',sans-serif; }
        [data-testid="stHeader"] { background:rgba(6,16,26,.78); border-bottom:1px solid var(--border); backdrop-filter:blur(18px); }
        [data-testid="stSidebar"] { background:linear-gradient(180deg,#0d1e2b 0%,#07131e 100%); border-right:1px solid var(--border); }
        [data-testid="stSidebar"] > div:first-child { padding-top:1rem; }
        .block-container { max-width:1540px; padding-top:1rem; padding-bottom:2.5rem; }
        h1,h2,h3 { color:var(--text)!important; letter-spacing:-.035em!important; } h1 { font-weight:800!important; }
        p,label,.stCaption { color:var(--muted); }
        .topbar { min-height:68px; display:flex; align-items:center; justify-content:space-between; gap:1rem; margin:0 0 1.15rem; padding:0 0 1rem; border-bottom:1px solid var(--border); }
        .topbar-brand { display:flex; align-items:center; gap:.7rem; min-width:0; }.topbar-logo { display:grid; place-items:center; width:34px; height:34px; flex:0 0 34px; border-radius:10px; color:#06202a; font-weight:900; background:linear-gradient(135deg,var(--accent),var(--accent-blue)); box-shadow:0 0 20px rgba(97,217,223,.24); }.topbar-title { color:#f4ffff; font-size:.87rem; font-weight:800; letter-spacing:.08em; text-transform:uppercase; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.topbar-meta { color:#7fa2ad; font:500 .62rem 'DM Mono',monospace; letter-spacing:.05em; margin-top:2px; }
        .system-status { display:flex; align-items:center; gap:.55rem; padding:.42rem .7rem; border:1px solid rgba(116,221,165,.25); border-radius:999px; background:rgba(45,131,94,.12); color:#a2eec3; font:500 .66rem 'DM Mono',monospace; white-space:nowrap; }.status-dot { display:inline-block; width:7px; height:7px; border-radius:50%; background:var(--success); box-shadow:0 0 10px var(--success); }
        .brand { display:flex; gap:.72rem; align-items:center; padding:.3rem .15rem 1.15rem; }.brand-mark { width:34px; height:34px; border-radius:10px; background:linear-gradient(135deg,var(--accent),var(--accent-blue)); box-shadow:0 0 25px rgba(97,217,223,.28); display:grid; place-items:center; color:#06202a; font-size:18px; font-weight:900; }.brand-title { font-size:.82rem; font-weight:800; letter-spacing:.11em; color:#effbfc; }.brand-sub { font:500 .61rem 'DM Mono',monospace; letter-spacing:.09em; color:#7f9da9; margin-top:2px; }
        [data-testid="stRadio"] label { border:1px solid transparent; border-radius:9px; padding:.37rem .54rem; margin:.04rem 0; transition:.18s ease; font-size:.86rem; } [data-testid="stRadio"] label:hover { background:rgba(97,217,223,.08); color:var(--text); } [data-testid="stRadio"] label:has(input:checked) { background:linear-gradient(90deg,rgba(97,217,223,.16),rgba(102,170,247,.08)); border-color:rgba(97,217,223,.17); } [data-testid="stRadio"] label:has(input:checked) p { color:#e9ffff; font-weight:700; }
        .nav-caption { color:#698793; font:500 .61rem 'DM Mono',monospace; letter-spacing:.1em; text-transform:uppercase; margin:1rem .15rem .35rem; }
        .hero { position:relative; overflow:hidden; padding:2.3rem; border:1px solid rgba(140,226,224,.2); border-radius:22px; background:linear-gradient(116deg,rgba(14,42,58,.98),rgba(15,82,99,.91) 62%,rgba(143,79,40,.78)); box-shadow:0 18px 42px rgba(0,0,0,.18); margin-bottom:1.2rem; }.hero:after { content:''; position:absolute; right:-64px; top:-130px; width:355px; height:355px; border:1px solid rgba(181,242,238,.18); border-radius:50%; box-shadow:0 0 0 44px rgba(181,242,238,.055),0 0 0 88px rgba(181,242,238,.035); }.hero h1 { position:relative; max-width:790px; margin:.55rem 0 0; font-size:clamp(1.8rem,3.2vw,2.85rem)!important; line-height:1.1; color:#fff!important; }.hero p { position:relative; max-width:730px; margin:.75rem 0 1rem; color:#daf0f3; font-size:1rem; line-height:1.65; }.eyebrow { position:relative; color:#bcefed; font:500 .68rem 'DM Mono',monospace; letter-spacing:.13em; text-transform:uppercase; }.live-pill,.status-badge { display:inline-flex; align-items:center; gap:.42rem; padding:.32rem .64rem; border-radius:999px; font:500 .65rem 'DM Mono',monospace; letter-spacing:.04em; }.live-pill { color:#e5ffff; border:1px solid rgba(222,255,251,.18); background:rgba(3,21,29,.28); }.live-dot { height:6px; width:6px; border-radius:50%; background:var(--accent); box-shadow:0 0 11px var(--accent); }
        .metric-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:.85rem; margin:.85rem 0 1.35rem; }.metric-card { position:relative; overflow:hidden; min-height:132px; padding:1.05rem 1.08rem; border:1px solid var(--border); border-radius:16px; background:linear-gradient(145deg,rgba(18,43,58,.95),rgba(9,24,35,.96)); box-shadow:0 10px 22px rgba(0,0,0,.11); transition:transform .18s ease,border-color .18s ease; }.metric-card:hover { transform:translateY(-3px); border-color:rgba(97,217,223,.38); }.metric-card:before { content:''; position:absolute; top:0; bottom:0; left:0; width:3px; background:linear-gradient(180deg,var(--accent),var(--accent-blue)); }.metric-card.warning:before { background:linear-gradient(180deg,var(--warning),#e58a45); }.metric-card.danger:before { background:linear-gradient(180deg,var(--danger),#d24d5e); }.metric-label { color:#8ea8b4; font:500 .64rem 'DM Mono',monospace; letter-spacing:.08em; text-transform:uppercase; }.metric-value { display:block; margin:.5rem 0 .28rem; color:#f4ffff; font-size:1.65rem; font-weight:800; letter-spacing:-.045em; }.metric-note { color:#79c9bb; font-size:.71rem; line-height:1.35; }.metric-icon { float:right; color:#79dcd9; font-size:1rem; }
        .section-title { display:flex; align-items:center; justify-content:space-between; gap:1rem; margin:1.35rem 0 .55rem; }.section-title h3 { margin:0; font-size:1rem!important; }.section-title span { color:#6f919f; font:500 .64rem 'DM Mono',monospace; letter-spacing:.08em; text-align:right; text-transform:uppercase; }.section-rule { height:1px; background:linear-gradient(90deg,var(--border),transparent); margin-bottom:.7rem; }
        .glass-card,.alert-card { border:1px solid var(--border); border-radius:15px; padding:1rem; background:var(--card-bg); box-shadow:0 8px 18px rgba(0,0,0,.08); }.alert-card { border-color:rgba(255,195,107,.28); }.status-badge.low,.status-badge.normal { color:#9bf0c3; background:rgba(43,151,114,.18); border:1px solid rgba(116,221,165,.24); }.status-badge.medium,.status-badge.warning { color:#ffe2a0; background:rgba(203,146,31,.18); border:1px solid rgba(255,195,107,.23); }.status-badge.high,.status-badge.critical,.status-badge.anomaly { color:#ffb5b5; background:rgba(210,73,74,.18); border:1px solid rgba(255,132,132,.23); }
        .process { display:flex; align-items:center; gap:8px; overflow-x:auto; overscroll-behavior-x:contain; padding:.45rem 0 1.05rem; }.stand { position:relative; min-width:118px; border:1px solid var(--border); border-radius:13px; padding:.85rem .8rem; background:linear-gradient(145deg,#102432,#0c1b27); font-size:.82rem; font-weight:700; }.stand:before { content:''; display:block; width:7px; height:7px; margin-bottom:.45rem; border-radius:50%; background:var(--success); box-shadow:0 0 10px rgba(116,221,165,.8); }.arrow { color:#4d7889; font-size:18px; }.muted { color:#7f9ba7; font:500 .61rem 'DM Mono',monospace; }
        .page-header { padding:.2rem 0 1.05rem; margin-bottom:1.15rem; border-bottom:1px solid var(--border); }.page-header .eyebrow { color:var(--accent); }.page-header h1 { margin:.42rem 0 .35rem; font-size:clamp(1.75rem,3vw,2.25rem)!important; line-height:1.15; }.page-header p { max-width:820px; margin:0; line-height:1.6; }.footer { border-top:1px solid var(--border); margin-top:1.5rem; padding:1.25rem 0 .15rem; color:#718c97; text-align:center; font:500 .67rem 'DM Mono',monospace; letter-spacing:.04em; }
        [data-testid="stMetric"] { padding:1rem; border:1px solid var(--border); border-radius:14px; background:var(--card-bg); } [data-testid="stMetricLabel"] { color:#91aab5; font:500 .66rem 'DM Mono',monospace; letter-spacing:.06em; text-transform:uppercase; } [data-testid="stMetricValue"] { color:#edf9fb; font-weight:800; }.stTabs [data-baseweb="tab-list"] { gap:.35rem; border-bottom:1px solid var(--border); }.stTabs [data-baseweb="tab"] { height:40px; padding:0 14px; border-radius:8px 8px 0 0; color:#8fa9b4; }.stTabs [aria-selected="true"] { background:rgba(97,217,223,.10)!important; color:#dffffd!important; }.stButton>button,[data-testid="stDownloadButton"]>button { min-height:2.6rem; border:1px solid rgba(97,217,223,.33); border-radius:9px; background:linear-gradient(135deg,#167d87,#216c9f); color:#fff; font-weight:700; box-shadow:0 6px 16px rgba(16,107,122,.20); }.stButton>button:hover,[data-testid="stDownloadButton"]>button:hover { border-color:var(--accent); color:#fff; box-shadow:0 7px 24px rgba(97,217,223,.19); }.stAlert,[data-testid="stDataFrame"] { border-radius:12px; } [data-testid="stDataFrame"] { border:1px solid var(--border); overflow:hidden; }.js-plotly-plot .plotly .modebar { border-radius:8px; background:rgba(10,25,36,.65)!important; }
        @media (max-width:1200px) { .metric-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }.block-container { padding-left:1.25rem; padding-right:1.25rem; } }
        @media (max-width:992px) { .topbar-meta { display:none; }.hero { padding:1.8rem; }.metric-card { min-height:122px; }.js-plotly-plot { max-width:100%; } }
        @media (max-width:768px) { .block-container { padding: .75rem 1rem 2rem; }.topbar { min-height:52px; margin-bottom:.8rem; padding-bottom:.75rem; }.topbar-title { max-width:200px; font-size:.74rem; }.system-status { padding:.34rem .5rem; font-size:.58rem; }.hero { padding:1.45rem 1.2rem; border-radius:17px; }.hero h1 { font-size:1.85rem!important; }.hero p { font-size:.91rem; }.metric-grid { grid-template-columns:1fr; gap:.68rem; }.metric-card { min-height:108px; }.section-title { align-items:flex-start; }.section-title span { max-width:42%; font-size:.57rem; }.process { margin-right:-1rem; padding-right:1rem; }.stand { min-width:108px; }.stTabs [data-baseweb="tab"] { padding:0 9px; font-size:.8rem; }.stButton>button,[data-testid="stDownloadButton"]>button { width:100%; }.page-header h1 { font-size:1.7rem!important; } }
        @media (max-width:576px) { .topbar-logo { width:30px; height:30px; flex-basis:30px; }.topbar-title { max-width:148px; font-size:.67rem; }.system-status { font-size:0; padding:.45rem; }.system-status .status-dot { margin:0; }.hero { padding:1.25rem 1rem; }.hero h1 { font-size:1.62rem!important; }.hero p { font-size:.86rem; }.metric-value { font-size:1.5rem; }.metric-label { font-size:.59rem; }.page-header p { font-size:.88rem; }.stNumberInput input { font-size:16px!important; } }
        </style>
        """,
        unsafe_allow_html=True,
    )
